package com.yeah.viewcontroller;

import com.yeah.service.DrawService;
import com.yeah.entities.TrainWinner;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;

import org.springframework.http.*;
import org.springframework.web.client.RestTemplate;

import java.time.LocalDate;
import java.util.Arrays;
import java.util.List;

@Controller
public class DrawViewController {

    private final DrawService drawService;

    @Autowired
    public DrawViewController(DrawService drawService) {
        this.drawService = drawService;
    }

    @GetMapping("/drawWinners")
    public String showDrawForm() {
        return "drawWinners";
    }

    @PostMapping("/drawWinners")
    public String drawWinners(@RequestParam("week") int week, @RequestParam("password") String password, Model model) {
        try {
            RestTemplate restTemplate = new RestTemplate();
            HttpHeaders headers = new HttpHeaders();
            headers.set("Authorization", password);
            HttpEntity<String> entity = new HttpEntity<>(headers);
            ResponseEntity<TrainWinner[]> response = restTemplate.exchange(
                "http://localhost:8080/api/train-scheduler/draw-winners/" + week,
                HttpMethod.POST,
                entity,
                TrainWinner[].class
            );
            if (response.getStatusCode().is2xxSuccessful() && response.getBody() != null) {
                model.addAttribute("winners", Arrays.asList(response.getBody()));
                model.addAttribute("success", true);
            } else {
                model.addAttribute("error", "Draw failed: " + response.getStatusCode());
            }
        } catch (Exception e) {
            model.addAttribute("error", e.getMessage());
        }
        model.addAttribute("week", week);
        return "drawWinners";
    }
}

package com.yeah.viewcontroller;

import com.yeah.service.DrawService;
import com.yeah.entities.TrainWinner;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;

import org.springframework.http.*;
import org.springframework.web.client.RestTemplate;
import org.springframework.web.client.HttpStatusCodeException;

import java.time.LocalDate;
import java.util.Arrays;
import java.util.List;

@Controller
public class DrawViewController {

    private final DrawService drawService;

    @Autowired
    public DrawViewController(DrawService drawService) {
        this.drawService = drawService;
    }

    @GetMapping("/drawWinners")
    public String showDrawForm() {
        return "drawWinners";
    }

    @PostMapping("/drawWinners")
    public String drawWinners(@RequestParam("week") int week, @RequestParam("password") String password, Model model) {
        try {
            RestTemplate restTemplate = new RestTemplate();
            HttpHeaders headers = new HttpHeaders();
            headers.set("Authorization", password);
            HttpEntity<String> entity = new HttpEntity<>(headers);
            ResponseEntity<TrainWinner[]> response = restTemplate.exchange(
                "http://localhost:8080/api/train-scheduler/draw-winners/" + week,
                HttpMethod.POST,
                entity,
                TrainWinner[].class
            );
            if (response.getStatusCode().is2xxSuccessful() && response.getBody() != null) {
                model.addAttribute("winners", Arrays.asList(response.getBody()));
                model.addAttribute("success", true);
            } else {
                model.addAttribute("error", "Draw failed: " + response.getStatusCode());
            }
        } catch (HttpStatusCodeException e) {
